/**
 * Explorer GraphQL operations over the locked SDL (`graphql/schema.graphql`).
 * Each document is annotated `TypedDocumentNode<Query, Variables>` — the types
 * are generated by GraphQL Code Generator from these literals
 * (`bun run codegen` in packages/graphql), so `client.query(DOC)` returns
 * typed data; no hand-mirrored result types, no unchecked casts (spec/15).
 */
import type { TypedDocumentNode } from "@graphql-typed-document-node/core";
import { gql } from "urql";
import type * as Ops from "../generated/operations";

// Shared source-location selection — one definition, spread into every
// document that fetches `source` (graphql-tag pluck resolves the
// interpolation for codegen; graphql-tag splices the doc at runtime).
export const SOURCE_FIELDS = gql`
  fragment SourceFields on SourceLocation {
    path
    line
    repositoryUrl
    repositoryRef
    viewUrl
  }
`;

// Shared row/prop types are indexed off the generated operation results —
// a component's contract is checked structurally against the real payload,
// so a field renamed in the SDL fails here, not at runtime.
export type EntityRefT = Ops.SimulateGatesQuery["simulateGates"]["entity"];
export type SourceLoc = Ops.ConceptsQuery["concepts"]["nodes"][number]["source"];
export type PageInfoT = Ops.ConceptsQuery["concepts"]["pageInfo"];
export type RuntimeInfoT = Ops.RuntimeInfoQuery["runtimeInfo"];

export const RUNTIME_INFO: TypedDocumentNode<Ops.RuntimeInfoQuery, Ops.RuntimeInfoQueryVariables> =
  gql`
  query RuntimeInfo {
    runtimeInfo {
      namespace { id key }
      environment
      runtimeRevision
      gitCommit
      sourceHash
      compilerVersion
    }
  }
`;

export type ConceptT = Ops.ConceptsQuery["concepts"]["nodes"][number];

export const CONCEPTS: TypedDocumentNode<Ops.ConceptsQuery, Ops.ConceptsQueryVariables> = gql`
  query Concepts($input: ConceptsInput) {
    concepts(input: $input) {
      nodes { id key name type description status
      domains { id key name }
      aliases { id alias }
      source { ...SourceFields }
      metadata }
      pageInfo { hasNextPage endCursor }
      totalCount
    }
  }

${SOURCE_FIELDS}
`;

export const CONCEPT: TypedDocumentNode<Ops.ConceptQuery, Ops.ConceptQueryVariables> = gql`
  query Concept($ref: EntityRefInput!) {
    concept(ref: $ref) {
      id key name type description status
      domains { id key name }
      aliases { id alias }
      source { ...SourceFields }
      metadata
      outgoingRelations { nodes { id type { key name } targetConcept { id key name } source { ...SourceFields } } totalCount }
      incomingRelations { nodes { id type { key name } sourceConcept { id key name } } totalCount }
    }
  }

${SOURCE_FIELDS}
`;

export const NEIGHBORHOOD: TypedDocumentNode<
  Ops.NeighborhoodQuery,
  Ops.NeighborhoodQueryVariables
> = gql`
  query Neighborhood($input: OntologyNeighborhoodInput!) {
    ontologyNeighborhood(input: $input) {
      center { id key name type status }
      concepts { id key name type status }
      relations { id type { key name } sourceConcept { id key name } targetConcept { id key name } }
      chunks { id key heading status knowledgeItem { key title } }
    }
  }
`;

export type NeighborhoodT = Ops.NeighborhoodQuery["ontologyNeighborhood"];

