// No singular `domain`/`selectionGroup` query exists in the SDL — detail
// pages pick the row from the unpaginated lists and fetch backlinks via
// filtered connections.

export const DIMENSIONS: TypedDocumentNode<Ops.DimensionsQuery, Ops.DimensionsQueryVariables> = gql`
  query Dimensions {
    dimensions {
      id key name description valueType cardinality category
      allowedOperators hierarchical required missingValueBehavior trust
      values(first: 200) { nodes { key name } }
      usedBy { entity { id } kind }
      source { ...SourceFields }
    }
  }

${SOURCE_FIELDS}
`;

export const DIMENSION: TypedDocumentNode<Ops.DimensionQuery, Ops.DimensionQueryVariables> = gql`
  query Dimension($ref: EntityRefInput!, $valuesAfter: String) {
    dimension(ref: $ref) {
      id key name description valueType cardinality category
      allowedOperators hierarchical required missingValueBehavior trust
      source { ...SourceFields }
      usedBy { entity { id key type } kind }
      values(first: 200, after: $valuesAfter) {
        nodes { id key name parent { id } children { id key } metadata }
        pageInfo { hasNextPage endCursor }
        totalCount
      }
    }
  }

${SOURCE_FIELDS}
`;

export const SELECTION_GROUPS: TypedDocumentNode<
  Ops.SelectionGroupsQuery,
  Ops.SelectionGroupsQueryVariables
> = gql`
  query SelectionGroups {
    selectionGroups {
      id key name entityType mode
      source { ...SourceFields }
      members { __typename ... on Skill { id key name priority } ... on Tool { id key name priority }
        ... on PromptFragment { id key name priority } ... on KnowledgeChunk { id key priority } }
    }
  }

${SOURCE_FIELDS}
`;

