export const RETRIEVE: TypedDocumentNode<Ops.RetrieveQuery, Ops.RetrieveQueryVariables> = gql`
  query Retrieve($input: RetrievalInput!) {
    retrieve(input: $input) {
      namespace { key } runtimeRevision query
      resolvedConcepts { concept { id key name } matchType matchedText score rank }
      results { score rank reasons { code message }
        chunk { id key heading ordinal knowledgeItem { key title } } }
      packedContext { estimatedTokens maxTokens maxChunks chunks { id key } }
      diagnostics {
        timings { stage milliseconds }
        candidateCounts { vector fullText trigram conceptLinked graphLinked unique
          afterLifecycle afterAuthorization afterApplicability afterSelectionGroups packed }
        exclusions { stage code message redacted chunk { id key type } }
        rankings { chunkId finalRank vectorRank vectorScore fullTextRank fullTextScore
          trigramRank trigramScore conceptRank graphRank rrfScore authorityScore priority }
        graphPaths { depth seedConcept { key } targetConcept { key }
          steps { relation { key } direction from { key } to { key } } }
        packing { considered packed skippedForBudget skippedForItemCap }
        warnings { code message }
        errors { code message }
      }
    }
  }
`;

export const ASSEMBLE: TypedDocumentNode<Ops.AssembleQuery, Ops.AssembleQueryVariables> = gql`
  query Assemble($input: AgentAssemblyInput!) {
    assembleAgent(input: $input) {
      namespace { key } runtimeRevision contextHash renderedPrompt
      template { id key name }
      task { text hash resolvedConcepts { concept { key name } matchType rank } }
      promptFragments { renderedOrder estimatedTokens sources
        fragment { id key name section inclusionMode }
        inclusionReasons { code message } }
      skills { rank score skill { id key name }
        inclusionReasons { code message } }
      tools { sources tool { id key name runtimeBinding }
        requiredBy { id key type } inclusionReasons { code message } }
      bootstrapKnowledge { score rank chunk { id key heading knowledgeItem { key } } }
      budgetUsage { skills maxSkills tools maxTools promptTokens maxPromptTokens
        bootstrapKnowledgeTokens maxBootstrapKnowledgeTokens }
      diagnostics {
        timings { stage milliseconds }
        warnings { code message }
        errors { code message }
        skillCandidates { entity { id key type } selected rank score code message
          causes { entityType entityId code message } }
        toolCandidates { entity { id key type } selected rank score code message
          causes { entityType entityId code message } }
        fragmentCandidates { entity { id key type } selected rank score code message
          causes { entityType entityId code message } }
        dependencyResolutions { requirement status reason
          sourceTool { key } targetTool { key } }
        bootstrapRetrieval {
          timings { stage milliseconds }
          candidateCounts { unique afterLifecycle afterAuthorization
            afterApplicability afterSelectionGroups packed }
          warnings { code message }
          errors { code message }
        }
      }
    }
  }
`;

