/** Global command-palette search — one request per entity type, keyed lists. */
export const GLOBAL_SEARCH: TypedDocumentNode<
  Ops.GlobalSearchQuery,
  Ops.GlobalSearchQueryVariables
> = gql`
  query GlobalSearch($q: String!) {
    concepts(input: {search: $q, first: 5}) { nodes { id key name status } }
    knowledgeItems(input: {search: $q, first: 5}) { nodes { id key title status } }
    domains(input: {search: $q, first: 5}) { nodes { id key name } }
    skills(input: {search: $q, first: 5}) { nodes { id key name status } }
    tools(input: {search: $q, first: 5}) { nodes { id key name status } }
    promptFragments(input: {search: $q, first: 5}) { nodes { id key name status } }
    agentTemplates { id key name status }
    selectionGroups { id key entityType mode }
    dimensions { id key name }
    retrievalProfiles { id key name }
    namespace { id key name }
  }
`;

